def solve(g):
    H,W=len(g),len(g[0])
    bgc=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bgc: continue
            if any((abs(i-si)+abs(j-sj))%2==0 for si,sj,_ in [(ii,jj,g[ii][jj]) for ii in range(H) for jj in range(W) if g[ii][jj]!=bgc]):
